import re,io
p='index.html'
s=open(p,encoding='utf-8').read()
# move stage before steps
start=s.index('  <div class="stage" id="stage"')
end=s.index('</div>\n</div>\n\n<section class="sec on-sheet" id="example">')
stage=s[start:end+len('</div>\n')]
s=s[:start]+s[end+len('</div>\n'):]
s=s.replace('<div class="scrolly">\n  <div class="steps">','<div class="scrolly">\n'+stage+'  <div class="steps">',1)
rep=[
('data-cap="DSEWiki: a reference for German software developers since the early 2000s, used as a notepad by agents."','data-cap="DSEWiki, 25 years old, used as a shared notepad by agents."'),
(' The operator keeps the stack they already have.',''),
('.scrolly{display:grid;grid-template-columns:minmax(0,calc(var(--gcol) + var(--tcol) + var(--cgap))) minmax(0,1fr);','.scrolly{display:grid;grid-template-columns:min(calc(var(--gcol) + var(--tcol) + var(--cgap)),54%) minmax(0,1fr);'),
('.sp.planted{background:var(--mark);border-color:var(--ink)}','.sp.planted{background:var(--sheet) linear-gradient(var(--mark),var(--mark)) no-repeat;background-size:100% 100%}'),
('/* narrow */','''@media (min-width:960px){
  .top{position:absolute;top:0;left:0;z-index:6;border-bottom:0;width:calc(var(--side) + min(calc(var(--gcol) + var(--tcol) + var(--cgap)), 0.54 * (100% - var(--side))) - var(--cgap))}
  .step.hero{padding-top:clamp(7rem,15vh,10rem)}
}
@media (min-width:960px) and (max-width:1180px){:root{--gcol:7rem}}
/* narrow */'''),
("""    el.style.left = Math.max(8, Math.min(vw - 8, x)) + 'px';""","""    const hw = k === 'Q' || k === 'B' || true ? el.offsetWidth / 2 : 0;
    el.style.left = Math.max(hw + 6, Math.min(vw - hw - 6, x)) + 'px';"""),
]
for a,b in rep:
    assert a in s, a[:60]
    s=s.replace(a,b)
open(p,'w',encoding='utf-8').write(s)
EOF
grep -n "—\|–" index.html | head; grep -n -i "seamless\|revolution\|game-chang\|unleash" index.html

